 "content": "def transform(grid):
    """Insert 2 into background cells flanked horizontally by identical markers."""
    out = [list(row) for row in grid]
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == row[c + 1] and row[c - 1] != background:
                out[r][c] = 2
    return out
